import{_ as d,a0 as s,w as l,s as p,ao as a,I as n,a1 as o,A as i,x as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度 | LCTT x X-CMD","titleTemplate":false,"description":"Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140714 Test read or write speed of usb and ssd drives with dd command on Linux","title":"Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度","tag":"201408","desc":""},"relativePath":"201408/20140714 Test read or write speed of usb and ssd drives with dd command on Linux.md","filePath":"[post].md"}'),u={name:"201408/20140714 Test read or write speed of usb and ssd drives with dd command on Linux.md"};function m(S,e,h,b,f,D){const t=s("Link");return l(),p("div",null,[e[19]||(e[19]=a(`<h1 id="linux系統中使用-dd-命令測試-usb-和-ssd-硬盤的讀寫速度" tabindex="-1">Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度 <a class="header-anchor" href="#linux系統中使用-dd-命令測試-usb-和-ssd-硬盤的讀寫速度" aria-label="Permalink to “Linux系統中使用 DD 命令測試 USB 和 SSD 硬盤的讀寫速度”">​</a></h1><h3 id="磁盤驅動器速度" tabindex="-1">磁盤驅動器速度 <a class="header-anchor" href="#磁盤驅動器速度" aria-label="Permalink to “磁盤驅動器速度”">​</a></h3><p>磁盤驅動器的速度是以一個單位時間內讀寫數據量的多少來衡量的。DD 命令是一個簡單的命令列工具，它可用對磁盤進行任意數據塊的讀取和寫入，同時可以度量讀取寫入的速度。</p><p>在這篇文章中，我們將會使用 DD 命令來測試 USB 和 SSD 磁盤的讀取和寫入速度。</p><p>數據傳輸速度不但取決於驅動盤本身，而且還與連接的接口有關。比如， USB 2.0 端口的最大傳輸速度是 35 兆字節/秒，所以如果您把一個支持高速傳輸的 USB 3.0 驅動盤插入 USB 2.0 端口的話，它實際的傳輸速度將是 2.0 端口的下限。</p><p>這對於 SSD 也是一樣的。 SSD 連接的 SATA 端口有不同的類型。平均是 375 兆字節/秒的 SATA 2.0 端口理論上最大傳輸速度是 3 Gbit/秒，而 SATA 3.0 是這個速度的兩倍。</p><h3 id="測試方法" tabindex="-1">測試方法 <a class="header-anchor" href="#測試方法" aria-label="Permalink to “測試方法”">​</a></h3><p>掛載上驅動盤，從終端進入此盤目錄下。然後使用 DD 命令，首先寫入固定大小塊的一個文件，接着讀取這個文件。</p><p>DD 命令通用語法格式如下：</p><pre><code>dd if=path/to/input_file of=/path/to/output_file bs=block_size count=number_of_blocks
</code></pre><p>當寫入到驅動盤的時候，我們簡單的從無窮無用字節的源 /dev/zero 讀取，當從驅動盤讀取的時候，我們讀取的是剛才的文件，並把輸出結果發送到無用的 /dev/null。在整個操作過程中， DD 命令會跟蹤數據傳輸的速度並且報告出結果。</p><h3 id="固態硬盤" tabindex="-1">固態硬盤 <a class="header-anchor" href="#固態硬盤" aria-label="Permalink to “固態硬盤”">​</a></h3><p>我們使用的是一塊“三星 Evo 120G” 的固態硬盤。它性價比很高，很適合剛開始用固態硬盤的用户，也是我的第一塊固態硬盤，並且也是市場上效果最好的固態硬盤之一。</p><p>這次實驗中，我們把硬盤接在 SATA 2.0 端口上。</p><h4 id="寫入速度" tabindex="-1">寫入速度 <a class="header-anchor" href="#寫入速度" aria-label="Permalink to “寫入速度”">​</a></h4><p>首先讓我們寫入固態硬盤</p><pre><code>$ dd if=/dev/zero of=./largefile bs=1M count=1024
1024+0 records in
1024+0 records out
1073741824 bytes (1.1 GB) copied, 4.82364 s, 223 MB/s
</code></pre><p>的大小實際上是相當大的。你可以嘗試用更小的尺寸如 64K 甚至是 4K 的。</p><h4 id="讀取速度" tabindex="-1">讀取速度 <a class="header-anchor" href="#讀取速度" aria-label="Permalink to “讀取速度”">​</a></h4><p>現在讀回這個文件。但是，得首先清除內存的緩存，以確保這個文件確實是從驅動盤讀取的。</p><p>運行下面的命令來清除內存緩存</p><pre><code>$ sudo sh -c &quot;sync &amp;&amp; echo 3 &gt; /proc/sys/vm/drop_caches&quot;
</code></pre><p>現在讀取此文件</p><pre><code>$ dd if=./largefile of=/dev/null bs=4k
165118+0 records in
165118+0 records out
676323328 bytes (676 MB) copied, 3.0114 s, 225 MB/s
</code></pre><p>在 Arch Linux 的維基頁上有一整頁的關於不同的廠商，如英特爾、三星、Sandisk 等提供的各類固態硬盤 讀/寫速度的信息。點擊如下的 url 可以查看相關信息。</p>`,25)),n("p",null,[o(t,{href:"http://wiki.archlinux.org/index.php/SSD_Benchmarking"},{default:i(()=>[...e[0]||(e[0]=[r("https://wiki.archlinux.org/index.php/SSD_Benchmarking",-1)])]),_:1})]),e[20]||(e[20]=a(`<h3 id="usb" tabindex="-1">USB <a class="header-anchor" href="#usb" aria-label="Permalink to “USB”">​</a></h3><p>此次實驗我們會測量普通的 USB/隨身筆的讀寫速度。驅動盤都是接入標準的 USB 2.0 端口的。首先用的是一個 4GB 大小的 sony USB 驅動盤，隨後用的是一個 16GB 大小的 strontium 驅動盤。</p><p>首先把驅動盤插入端口，並掛載上，使其可讀。然後從命令列下面進入掛載的文件目錄下。</p><h4 id="sony-4gb-寫入" tabindex="-1">Sony 4GB - 寫入 <a class="header-anchor" href="#sony-4gb-寫入" aria-label="Permalink to “Sony 4GB - 寫入”">​</a></h4><p>這個實驗中，用 DD 命令向驅動盤寫入一個有 10000 塊，每塊 8K 字節的文件。</p><pre><code># dd if=/dev/zero of=./largefile bs=8k count=10000
10000+0 records in
10000+0 records out
81920000 bytes (82 MB) copied, 11.0626 s, 7.4 MB/s
</code></pre><p>因此，寫入速度約為7.5兆字節/秒。這是一個很低的數字。</p><h4 id="sony-4gb-讀取" tabindex="-1">Sony 4GB - 讀取 <a class="header-anchor" href="#sony-4gb-讀取" aria-label="Permalink to “Sony 4GB - 讀取”">​</a></h4><p>把相同的文件讀取回來，測試速度。首先運行如下命令清除內存緩存。</p><pre><code>$ sudo sh -c &quot;sync &amp;&amp; echo 3 &gt; /proc/sys/vm/drop_caches&quot;
</code></pre><p>現在就可以使用 DD 命令來讀取文件了。</p><pre><code># dd if=./largefile of=/dev/null bs=8k
8000+0 records in
8000+0 records out
65536000 bytes (66 MB) copied, 2.65218 s, 24.7 MB/s
</code></pre><p>讀取速度出來大約是25兆字節/秒，這大致跟廉價 USB 驅動盤的標準相匹配吧。</p><blockquote><p>USB2.0 理論上最大信號傳輸速率為480兆比特/秒，最小為60兆字節/秒。然而，由於各種限制實際傳輸速率大約280兆比特/秒和35兆字節/秒之間。除了這個，實際的速度還取決於驅動盤本身的質量好壞以及其他的因素。</p></blockquote><p>上面實驗中， USB 驅動盤插入USB 2.0 端口，讀取的速度達到了 24.7兆字節/秒，這是很不錯的讀速度。但寫入速度就不敢恭維了。</p><p>下面讓我們用 16GB 的 Strontium 驅動盤來做相同的實驗。雖然 Strontium 的 USB 驅動盤很穩定，但它也是一款很便宜的品牌。</p><h4 id="strontium-16gb-盤寫入速度" tabindex="-1">Strontium 16gb 盤寫入速度 <a class="header-anchor" href="#strontium-16gb-盤寫入速度" aria-label="Permalink to “Strontium 16gb 盤寫入速度”">​</a></h4><pre><code># dd if=/dev/zero of=./largefile bs=64k count=1000
1000+0 records in
1000+0 records out
65536000 bytes (66 MB) copied, 8.3834 s, 7.8 MB/s
</code></pre><h4 id="strontium-16gb-盤讀取速度" tabindex="-1">Strontium 16gb 盤讀取速度 <a class="header-anchor" href="#strontium-16gb-盤讀取速度" aria-label="Permalink to “Strontium 16gb 盤讀取速度”">​</a></h4><pre><code># sudo sh -c &quot;sync &amp;&amp; echo 3 &gt; /proc/sys/vm/drop_caches&quot;

# dd if=./largefile of=/dev/null bs=8k
8000+0 records in
8000+0 records out
65536000 bytes (66 MB) copied, 2.90366 s, 22.6 MB/s
</code></pre><p>它的讀取速度就要比 Sony 的低了。</p><h3 id="參考資料" tabindex="-1">參考資料 <a class="header-anchor" href="#參考資料" aria-label="Permalink to “參考資料”">​</a></h3>`,22)),n("ul",null,[n("li",null,[o(t,{href:"http://en.wikipedia.org/wiki/USB"},{default:i(()=>[...e[1]||(e[1]=[r("http://en.wikipedia.org/wiki/USB",-1)])]),_:1})]),n("li",null,[o(t,{href:"http://wiki.archlinux.org/index.php/SSD_Benchmarking"},{default:i(()=>[...e[2]||(e[2]=[r("https://wiki.archlinux.org/index.php/SSD_Benchmarking",-1)])]),_:1})])]),e[21]||(e[21]=n("hr",null,null,-1)),e[22]||(e[22]=n("p",null,[n("img",{src:"http://0.gravatar.com/avatar/e23f2767e6907e798da5b28694a2bf28?s=64&d=&r=G",alt:""})],-1)),e[23]||(e[23]=n("p",null,"關於 Silver Moon",-1)),n("p",null,[e[5]||(e[5]=r("Php 開發者, 博主 和 Linux 愛好者. 通過 ",-1)),o(t,{href:"m00n.silv3r@gmail.com"},{default:i(()=>[...e[3]||(e[3]=[r("m00n.silv3r@gmail.com",-1)])]),_:1}),e[6]||(e[6]=r(" 或者 ",-1)),o(t,{href:"http://plus.google.com/117145272367995638274/posts"},{default:i(()=>[...e[4]||(e[4]=[r("Google+",-1)])]),_:1}),e[7]||(e[7]=r(" 可聯繫到他。",-1))]),e[24]||(e[24]=n("hr",null,null,-1)),n("p",null,[e[9]||(e[9]=r("via: ",-1)),o(t,{href:"http://www.binarytides.com/linux-test-drive-speed/"},{default:i(()=>[...e[8]||(e[8]=[r("http://www.binarytides.com/linux-test-drive-speed/",-1)])]),_:1})]),n("p",null,[e[12]||(e[12]=r("譯者：",-1)),o(t,{href:"https://github.com/runningwater"},{default:i(()=>[...e[10]||(e[10]=[r("runningwater",-1)])]),_:1}),e[13]||(e[13]=r(" 校對：",-1)),o(t,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:i(()=>[...e[11]||(e[11]=[r("校對者ID",-1)])]),_:1})]),n("p",null,[e[16]||(e[16]=r("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[14]||(e[14]=[r("LCTT",-1)])]),_:1}),e[17]||(e[17]=r(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:i(()=>[...e[15]||(e[15]=[r("Linux中國",-1)])]),_:1}),e[18]||(e[18]=r(" 榮譽推出",-1))])])}const k=d(u,[["render",m]]);export{x as __pageData,k as default};
